/**
 * Custom Clawd Variant for Claude Code
 * Theme: Ocean Blue with Top Hat and Arms
 * 
 * Design Brief:
 * - Recolor mascot to ocean blue
 * - Add top hat accessory
 * - Add both arms
 * - Keep mascot recognizable
 */

// Color Configuration
const clawdTheme = {
  // Ocean Blue color scheme
  rgb: {
    clawd_body: "rgb(100,149,237)",
    clawd_background: "rgb(0,0,0)"
  },
  // ANSI fallback for 8/16-color terminals
  ansi: {
    clawd_body: "ansi:blueBright",
    clawd_background: "ansi:black"
  }
};

// Small Prompt Icon Clawd (with top hat and both arms)
const smallClawd = {
  description: "Clawd mascot with top hat and arms - for prompt icon",
  art: [
    "   ┌───┐   ",
    "  ╱▐▛███▜▌╲ ",
    "  ▝▜█████▛▘ ",
    "    ▘▘ ▝▝  "
  ],
  jsx: `
<Box flexDirection="column">
  <Text>
    <Text color="clawd_body">   ┌───┐   </Text>
  </Text>
  <Text>
    <Text color="clawd_body">  ╱</Text>
    <Text color="clawd_body" backgroundColor="clawd_background">▐▛███▜▌</Text>
    <Text color="clawd_body">╲ </Text>
  </Text>
  <Text>
    <Text color="clawd_body">  ▝▜</Text>
    <Text color="clawd_body" backgroundColor="clawd_background">█████</Text>
    <Text color="clawd_body">▛▘ </Text>
  </Text>
  <Text color="clawd_body">    ▘▘ ▝▝  </Text>
</Box>
  `
};

// Large Loading Screen Clawd (with top hat and arms)
const largeClawd = {
  description: "Clawd mascot with top hat and arms - for loading screen",
  art: [
    "      ╭─────╮      ",
    "     ────────      ",
    "    ╱╱▐███████▌╲╲  ",
    "   ╱▝▜█████████▛▘╲ ",
    "  ▝▜█████████████▛▘",
    "    ▝▜█████████▛▝  ",
    "      ▘▘   ▝▝      ",
    "       ▘▝▘▝▘       "
  ],
  jsx: `
<Box flexDirection="column">
  <Text color="clawd_body">      ╭─────╮      </Text>
  <Text color="clawd_body">     ────────      </Text>
  <Text>
    <Text color="clawd_body">    ╱╱</Text>
    <Text color="clawd_body" backgroundColor="clawd_background">▐███████▌</Text>
    <Text color="clawd_body">╲╲  </Text>
  </Text>
  <Text>
    <Text color="clawd_body">   ╱▝▜</Text>
    <Text color="clawd_body" backgroundColor="clawd_background">█████████</Text>
    <Text color="clawd_body">▛▘╲ </Text>
  </Text>
  <Text>
    <Text color="clawd_body">  ▝▜</Text>
    <Text color="clawd_body" backgroundColor="clawd_background">█████████████</Text>
    <Text color="clawd_body">▛▘</Text>
  </Text>
  <Text>
    <Text color="clawd_body">    ▝▜</Text>
    <Text color="clawd_body" backgroundColor="clawd_background">█████████</Text>
    <Text color="clawd_body">▛▝  </Text>
  </Text>
  <Text color="clawd_body">      ▘▘   ▝▝      </Text>
  <Text color="clawd_body">       ▘▝▘▝▘       </Text>
</Box>
  `
};

// Export for use in CLI
module.exports = {
  clawdTheme,
  smallClawd,
  largeClawd
};

// Display functions for testing
function displaySmallClawd() {
  console.log("Small Clawd (Prompt Icon):" );
  smallClawd.art.forEach(line => console.log(line));
  console.log();
}

function displayLargeClawd() {
  console.log("Large Clawd (Loading Screen):" );
  largeClawd.art.forEach(line => console.log(line));
  console.log();
}

// Run display if executed directly
if (require.main === module) {
  console.log("=== Custom Clawd Variant: Ocean Blue ===");
  console.log("Color: rgb(100,149,237) / ansi:blueBright");
  console.log();
  displaySmallClawd();
  displayLargeClawd();
}
ENDOFFILE
